CREATE TABLE rule_ship_security_rating(security_rating smallint PRIMARY KEY CHECK(security_rating BETWEEN 0 AND 3),difficulty_rule_id bigint NOT NULL REFERENCES rule_difficulty(rule_id),is_starship_default boolean NOT NULL,is_typical_vessel_rating boolean NOT NULL,UNIQUE(difficulty_rule_id));
INSERT INTO rule_ship_security_rating SELECT personal.rating,personal.difficulty_rule_id,personal.rating=0,personal.rating=2 FROM rule_personal_security_difficulty personal JOIN rule_personal_software_family family ON family.rule_id=personal.software_rule_id WHERE family.software_code='security';
CREATE TABLE ship_security_computer_state(ship_id bigint PRIMARY KEY,campaign_id bigint NOT NULL,security_rating smallint NOT NULL DEFAULT 0 REFERENCES rule_ship_security_rating(security_rating),concurrency_version bigint NOT NULL DEFAULT 1 CHECK(concurrency_version>0),configured_at timestamptz NOT NULL DEFAULT clock_timestamp(),FOREIGN KEY(ship_id,campaign_id) REFERENCES ship_ship(ship_id,campaign_id));
CREATE TABLE ship_security_cyber_attempt(cyber_attempt_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,public_id uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE,ship_id bigint NOT NULL,campaign_id bigint NOT NULL,cybersecurity_task_code text NOT NULL REFERENCES rule_ship_cybersecurity_task(cybersecurity_task_code),task_command_id bigint NOT NULL UNIQUE REFERENCES cmd_actor_task_receipt(command_id),security_rating_snapshot smallint NOT NULL REFERENCES rule_ship_security_rating(security_rating),effective_difficulty_rule_id bigint NOT NULL REFERENCES rule_difficulty(rule_id),task_succeeded boolean NOT NULL,recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),FOREIGN KEY(ship_id,campaign_id) REFERENCES ship_ship(ship_id,campaign_id));
CREATE FUNCTION ship_validate_cyber_attempt() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE state ship_security_computer_state%ROWTYPE;profile rule_ship_cybersecurity_task%ROWTYPE;task cmd_actor_task_receipt%ROWTYPE;actor_campaign bigint;expected bigint;BEGIN SELECT * INTO STRICT state FROM ship_security_computer_state WHERE ship_id=NEW.ship_id;SELECT * INTO STRICT profile FROM rule_ship_cybersecurity_task WHERE cybersecurity_task_code=NEW.cybersecurity_task_code;SELECT * INTO STRICT task FROM cmd_actor_task_receipt WHERE command_id=NEW.task_command_id;SELECT campaign_id INTO STRICT actor_campaign FROM actor_actor WHERE actor_id=task.actor_id;expected:=CASE WHEN profile.security_software_defines_difficulty THEN (SELECT difficulty_rule_id FROM rule_ship_security_rating WHERE security_rating=state.security_rating) ELSE profile.difficulty_rule_id END;
 IF state.campaign_id<>NEW.campaign_id OR actor_campaign<>NEW.campaign_id OR NEW.security_rating_snapshot<>state.security_rating OR NEW.effective_difficulty_rule_id<>expected OR task.skill_rule_id<>profile.computer_skill_rule_id OR task.difficulty_rule_id<>expected OR NEW.task_succeeded<>task.succeeded THEN RAISE EXCEPTION 'Cybersecurity attempt must match ship rating and the published Computer task, difficulty, and result' USING ERRCODE='23514';END IF;RETURN NEW;END $$;
CREATE TRIGGER ship_cyber_attempt_valid BEFORE INSERT ON ship_security_cyber_attempt FOR EACH ROW EXECUTE FUNCTION ship_validate_cyber_attempt();
CREATE FUNCTION ship_reject_cyber_attempt_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Ship cybersecurity attempts are immutable';END $$;CREATE TRIGGER ship_cyber_attempt_immutable BEFORE UPDATE OR DELETE ON ship_security_cyber_attempt FOR EACH ROW EXECUTE FUNCTION ship_reject_cyber_attempt_mutation();
